BEGIN TRANSACTION;
CREATE TABLE evenements_historique (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                camera_id TEXT NOT NULL,
                timestamp REAL NOT NULL,
                type_evenement TEXT NOT NULL,
                gravite TEXT DEFAULT 'info',
                statut TEXT DEFAULT 'non_traite',
                acquitte_par TEXT,
                acquitte_le REAL,
                payload_json TEXT NOT NULL
            );
CREATE TABLE kv_store (
                key TEXT PRIMARY KEY,
                value_json TEXT NOT NULL,
                updated_at REAL NOT NULL
            );
CREATE TABLE sessions_revoquees (
                jti TEXT PRIMARY KEY,
                exp REAL NOT NULL,
                revoque_le REAL NOT NULL
            );
CREATE INDEX idx_hist_cam_ts ON evenements_historique(camera_id, timestamp DESC);
CREATE INDEX idx_hist_ts ON evenements_historique(timestamp DESC);
CREATE INDEX idx_hist_statut ON evenements_historique(statut);
CREATE INDEX idx_sessions_revoquees_exp ON sessions_revoquees(exp);
DELETE FROM "sqlite_sequence";
COMMIT;
